CREATE TABLE s_stripe_environment(id INTEGER PRIMARY KEY CHECK(id=1),mode TEXT NOT NULL CHECK(mode IN('test','live')));
CREATE TRIGGER s_stripe_environment_no_update BEFORE UPDATE ON s_stripe_environment BEGIN SELECT RAISE(ABORT,'payment environments cannot be mixed'); END;
CREATE TRIGGER s_stripe_environment_no_delete BEFORE DELETE ON s_stripe_environment BEGIN SELECT RAISE(ABORT,'payment environments cannot be mixed'); END;
CREATE TABLE s_stripe_config(id TEXT PRIMARY KEY,account_id TEXT NOT NULL,mode TEXT NOT NULL CHECK(mode IN('test','live')),kind TEXT NOT NULL CHECK(kind IN('operating','trust')),bank_account_id TEXT REFERENCES s_trust_accounts(id),external_bank_id TEXT,protection_document_id TEXT,protection_digest TEXT,protection_reference TEXT,approved_by TEXT NOT NULL,approved_at TEXT NOT NULL);
CREATE TABLE s_stripe_checkouts(id TEXT PRIMARY KEY,request_key TEXT NOT NULL UNIQUE,bill_id TEXT NOT NULL REFERENCES s_bills(id),cents INTEGER NOT NULL CHECK(cents>0),currency TEXT NOT NULL CHECK(currency='usd'),status TEXT NOT NULL CHECK(status IN('creating','open','pending','paid','returned','failed','expired','uncertain')),purpose TEXT NOT NULL CHECK(purpose IN('operating','trust')),ledger_id TEXT REFERENCES s_trust_ledgers(id),config_id TEXT NOT NULL REFERENCES s_stripe_config(id),session_id TEXT UNIQUE,payment_intent_id TEXT UNIQUE,created_by TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE UNIQUE INDEX s_stripe_one_live_collection ON s_stripe_checkouts(bill_id,purpose) WHERE status IN('creating','open','pending','uncertain');
CREATE TABLE s_stripe_adjustments(id TEXT PRIMARY KEY,checkout_id TEXT NOT NULL REFERENCES s_stripe_checkouts(id),provider_ref TEXT NOT NULL UNIQUE,cents INTEGER NOT NULL CHECK(cents>0),kind TEXT NOT NULL CHECK(kind IN('return','refund','dispute')),at TEXT NOT NULL);
CREATE TABLE s_stripe_events(id TEXT PRIMARY KEY,checkout_id TEXT NOT NULL REFERENCES s_stripe_checkouts(id),type TEXT NOT NULL,status TEXT NOT NULL,cents INTEGER NOT NULL,at TEXT NOT NULL);
CREATE TRIGGER s_stripe_config_no_update BEFORE UPDATE ON s_stripe_config BEGIN SELECT RAISE(ABORT,'processor approvals are immutable'); END;
CREATE TRIGGER s_stripe_config_no_delete BEFORE DELETE ON s_stripe_config BEGIN SELECT RAISE(ABORT,'processor approvals are immutable'); END;
CREATE TRIGGER s_stripe_adjustments_no_update BEFORE UPDATE ON s_stripe_adjustments BEGIN SELECT RAISE(ABORT,'processor adjustments are append-only'); END;
CREATE TRIGGER s_stripe_adjustments_no_delete BEFORE DELETE ON s_stripe_adjustments BEGIN SELECT RAISE(ABORT,'processor adjustments are append-only'); END;
CREATE TRIGGER s_stripe_events_no_update BEFORE UPDATE ON s_stripe_events BEGIN SELECT RAISE(ABORT,'processor events are append-only'); END;
CREATE TRIGGER s_stripe_events_no_delete BEFORE DELETE ON s_stripe_events BEGIN SELECT RAISE(ABORT,'processor events are append-only'); END;
